//! BoringSSL cryptography backend for [`tpm2::crypto`].
//!
//! This crate is `#![no_std]` (and does not require `alloc`). It binds to
//! BoringSSL via:
//! 1. The `bssl-sys` bindings generated by BoringSSL's CMake build
//!    (`-DRUST_BINDINGS=<target>`), which `build.rs` copies from
//!    `${BORINGSSL_BUILD_DIR}/rust/bssl-sys` and this crate `include!`s in a
//!    private `bssl_sys` module, for public FIPS-module and libcrypto symbols.
//! 2. `bindgen`-generated bindings (in `build.rs`) to
//!    `crypto/fipsmodule/bcm_interface.h` (and `crypto/curve25519/internal.h`
//!    under `non-fips`) for direct BoringSSL Cryptographic Module (`BCM_*`)
//!    entry points that `bssl-sys`'s `wrapper.h` does not re-export.
//!
//! ## Cargo Features
//!
//! - `non-fips` (disabled by default): Enables `Ed25519` (`EdwardsCurve<32>`,
//!   pure `EdDSA` and `HashEdDSA` / `Ed25519ph`) and `X25519`
//!   (`MontgomeryCurve<32>`), which are implemented in BoringSSL's non-FIPS
//!   `crypto/curve25519` module outside `bcm`. When `non-fips` is disabled,
//!   `<BoringSsl as Ecc>::Ed25519` and `<BoringSsl as Ecc>::X25519` are bound
//!   to `!`.
//!
//! ## Building
//!
//! Building `tpm2-boringssl` requires a BoringSSL source tree and a CMake
//! build directory configured with `-DRUST_BINDINGS=<target-triple>` and
//! (recommended) a symbol prefix:
//!
//! ```sh
//! cd "$BORINGSSL_SOURCE_DIR"
//! cmake -GNinja -B build -DRUST_BINDINGS=x86_64-unknown-linux-gnu -DBORINGSSL_PREFIX=BSSL
//! ninja -C build
//! ```
//!
//! Passing `-DBORINGSSL_PREFIX=BSSL` prefixes BoringSSL's exported C and C++
//! symbols so `tpm2-boringssl` can be linked into the same (test) binary as
//! OpenSSL (e.g. `tpm2-openssl`) without symbol clashes. `build.rs`
//! automatically detects `BORINGSSL_PREFIX` from
//! `${BORINGSSL_BUILD_DIR}/CMakeCache.txt`.
//!
//! Environment variables read at build time:
//! - `BORINGSSL_SOURCE_DIR` (required): path to the BoringSSL source tree
//!   containing `include/` and `crypto/fipsmodule/bcm_interface.h`.
//! - `BORINGSSL_BUILD_DIR` (required): path to the BoringSSL CMake build
//!   directory (containing `libcrypto.a` and
//!   `rust/bssl-sys/wrapper_<target>.rs`).
//! - `BINDGEN` (optional): path to the `bindgen` CLI binary (default:
//!   `bindgen` on `PATH`).
//! - `BORINGSSL_RUST_CPPLIB` (optional): C++ runtime library to link (default:
//!   `c++` on macOS, `stdc++` on other Unix targets).
//!
//! `build.rs` fails with an error if a required variable is missing. No other
//! crate in the workspace depends on BoringSSL. See `README.md` for details.
//!
//! ## Supported Algorithms
//!
//! | Family | Algorithm / Curve / Mode | Supported | BoringSSL Layer | Entry Points |
//! |--------|--------------------------|-----------|-----------------|--------------|
//! | `Hash` | `SHA-1` | Yes | BCM (internal FIPS module) | `BCM_sha1_init`, `BCM_sha1_update`, `BCM_sha1_final` |
//! | `Hash` | `SHA-256` | Yes | BCM (internal FIPS module) | `BCM_sha256_init`, `BCM_sha256_update`, `BCM_sha256_final` |
//! | `Hash` | `SHA-384` | Yes | BCM (internal FIPS module) | `BCM_sha384_init`, `BCM_sha384_update`, `BCM_sha384_final` |
//! | `Hash` | `SHA-512` | Yes | BCM (internal FIPS module) | `BCM_sha512_init`, `BCM_sha512_update`, `BCM_sha512_final` |
//! | `Hash` | `SM3-256`, `SHA3-256/384/512` | No (`!`) | — | — |
//! | `Hmac` | `HMAC-SHA-1/256/384/512` | Yes | Public FIPS-module API | `HMAC_CTX_new`, `HMAC_Init_ex`, `HMAC_Update`, `HMAC_Final` |
//! | `Hmac` | `HMAC-SM3-256`, `HMAC-SHA3-*` | No (`!`) | — | — |
//! | `Cmac` | `AES-128/192/256-CMAC` | Yes | Public FIPS-module API | `CMAC_CTX_new`, `CMAC_Init`, `CMAC_Update`, `CMAC_Final` |
//! | `Cmac` | `SM4-128`, `Camellia-*` | No (`!`) | — | — |
//! | `Symmetric` | `AES-128/192/256` key setup & `ECB` | Yes | BCM (internal FIPS module) | `BCM_aes_set_encrypt_key`, `BCM_aes_set_decrypt_key`, `BCM_aes_encrypt`, `BCM_aes_decrypt` |
//! | `Symmetric` | `AES-128/192/256` `CTR`, `OFB`, `CBC`, `CFB` | Yes | Public FIPS-module API | `AES_ctr128_encrypt`, `AES_ofb128_encrypt`, `AES_cbc_encrypt`, `AES_cfb128_encrypt` |
//! | `Symmetric` | `SM4-128`, `Camellia-*` | No (`!`) | — | — |
//! | `Random` / `Rng` | `BoringSslRng` (`AES-256-CTR DRBG`) | Yes | BCM + Public FIPS-module API | `BCM_rand_bytes`, `BCM_sha384_*`, `CTR_DRBG_new`, `CTR_DRBG_generate`, `CTR_DRBG_reseed` |
//! | `Rsa` | `RSA-1024/2048/3072/4096` (`Raw`, `RSAES`, `OAEP`, `RSASSA`, `RSAPSS`) | Yes | Public FIPS-module API | `RSA_new_public_key`, `RSA_new_private_key`, `RSA_encrypt`, `RSA_decrypt`, `EVP_PKEY_encrypt`, `EVP_PKEY_decrypt` (OAEP), `RSA_sign`, `RSA_verify`, `RSA_sign_pss_mgf1`, `RSA_verify_pss_mgf1`, `BN_primality_test` |
//! | `Ecc` | `NIST P-224/P-256/P-384/P-521` (`ECDH`, `ECDSA`, `ECSchnorr`) | Yes | Public FIPS-module API | `EC_group_p224/256/384/521`, `EC_POINT_mul`, `ECDSA_sign_p1363`, `ECDSA_verify_p1363` |
//! | `Ecc` | `Ed25519` (`EdDSA`, `HashEdDSA`), `X25519` (`ECDH`) | Yes (`non-fips` feature) | Non-FIPS libcrypto (`curve25519`) | `ED25519_keypair_from_seed`, `ED25519_sign`, `ED25519_verify`, `ED25519_sign_prehashed`, `ED25519_verify_prehashed`, `X25519`, `X25519_public_from_private`, `x25519_ge_*` |
//! | `Ecc` | `NIST P-192`, `BN-P256/P638`, `SM2`, `Brainpool`, `Ed448`, `X448` | No (`!`) | — | — |
//! | `Mldsa` | `ML-DSA-44`, `ML-DSA-65`, `ML-DSA-87` (`ML-DSA` pure, external `µ`, `HashML-DSA`) | Yes | BCM (internal FIPS module) | `BCM_mldsa{44,65,87}_parse_public_key`, `BCM_mldsa{44,65,87}_generate_key_external_entropy`, `BCM_mldsa{44,65,87}_prehash_*`, `BCM_mldsa{44,65,87}_sign_mu_internal`, `BCM_mldsa{44,65,87}_verify_message_representative`, `BCM_mldsa{44,65,87}_sign_internal`, `BCM_mldsa{44,65,87}_verify_internal` |
//! | `Mlkem` | `ML-KEM-768`, `ML-KEM-1024` | Yes | BCM (internal FIPS module) | `BCM_mlkem{768,1024}_parse_public_key`, `BCM_mlkem{768,1024}_generate_key_external_seed`, `BCM_mlkem{768,1024}_encap_external_entropy`, `BCM_mlkem{768,1024}_decap` |
//! | `Mlkem` | `ML-KEM-512` | No (`!`) | — | — |
//! | `Crypto` | `ct_eq` | Yes | Public FIPS-module API | `CRYPTO_memcmp` |

#![no_std]

/// Bindings to BoringSSL's public API, generated by BoringSSL's CMake build
/// (`-DRUST_BINDINGS=<target>`) for its `bssl-sys` crate and copied into
/// `OUT_DIR` by `build.rs`.
#[allow(
    unknown_lints,
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    unnecessary_transmutes,
    dead_code,
    unsafe_op_in_unsafe_fn,
    clippy::all,
    clippy::pedantic
)]
mod bssl_sys {
    include!(concat!(env!("OUT_DIR"), "/bssl_sys_bindings.rs"));
}

mod bcm;
mod cmac;
#[cfg(feature = "non-fips")]
mod curve25519;
mod ecc;
mod hash;
mod hmac;
mod mldsa;
mod mlkem;
mod rng;
mod rsa;
mod symmetric;

#[cfg(feature = "non-fips")]
pub use curve25519::{
    BoringSslEd25519, BoringSslEd25519PrivateKey, BoringSslEd25519PublicKey, BoringSslX25519,
    BoringSslX25519PrivateKey, BoringSslX25519PublicKey,
};
pub use {
    cmac::BoringSslCmacState,
    ecc::{BoringSslEccCurve, BoringSslEccPrivateKey, BoringSslEccPublicKey},
    hash::BoringSslHashState,
    hmac::BoringSslHmacState,
    mldsa::{
        BoringSslMldsa44, BoringSslMldsa44PrivateKey, BoringSslMldsa44PublicKey, BoringSslMldsa65,
        BoringSslMldsa65PrivateKey, BoringSslMldsa65PublicKey, BoringSslMldsa87,
        BoringSslMldsa87PrivateKey, BoringSslMldsa87PublicKey,
    },
    mlkem::{
        BoringSslMlkem768, BoringSslMlkem768PrivateKey, BoringSslMlkem768PublicKey,
        BoringSslMlkem1024, BoringSslMlkem1024PrivateKey, BoringSslMlkem1024PublicKey,
    },
    rng::BoringSslRng,
    rsa::{BoringSslRsa, BoringSslRsaPrivateKey, BoringSslRsaPublicKey},
    symmetric::BoringSslAesKey,
};

use tpm2::crypto::Crypto;

/// BoringSSL cryptography backend implementing [`tpm2::crypto::Crypto`].
#[derive(Debug, Default, Clone, Copy)]
pub struct BoringSsl;

impl Crypto for BoringSsl {
    fn ct_eq(a: &[u8], b: &[u8]) -> bool {
        if a.len() != b.len() {
            return false;
        }
        if a.is_empty() {
            return true;
        }
        unsafe { bssl_sys::CRYPTO_memcmp(a.as_ptr().cast(), b.as_ptr().cast(), a.len()) == 0 }
    }
}
